export function getOpinionBrief(id?: string): OpinionBrief | undefined {
  if (!id) return undefined;
  return Object.prototype.hasOwnProperty.call(OPINION_BRIEFS, id)
    ? OPINION_BRIEFS[id]
    : undefined;
}
